public int rob(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return nums[0];
    }
    return Math.max(robRange(nums, 0, n - 2), robRange(nums, 1, n - 1));
}

private int robRange(int[] nums, int lo, int hi) {
    return robFrom(nums, lo, hi);
}

private int robFrom(int[] nums, int i, int hi) {
    if (i > hi) {
        return 0;
    }
    int robThis = nums[i] + robFrom(nums, i + 2, hi);
    int skipThis = robFrom(nums, i + 1, hi);
    return Math.max(robThis, skipThis);
}

