private int robRange(int[] nums, int lo, int hi) {
    int[] memo = new int[nums.length];
    Arrays.fill(memo, -1);
    return solve(nums, lo, hi, memo);
}

private int solve(int[] nums, int i, int hi, int[] memo) {
    if (i > hi) {
        return 0;
    }
    if (memo[i] != -1) {
        return memo[i];
    }
    int robThis = nums[i] + solve(nums, i + 2, hi, memo);
    int skipThis = solve(nums, i + 1, hi, memo);
    memo[i] = Math.max(robThis, skipThis);
    return memo[i];
}

