def rob(self, nums: list[int]) -> int:
    n = len(nums)
    if n == 1:
        return nums[0]

    def rob_range(lo: int, hi: int) -> int:
        memo: dict[int, int] = {}

        def solve(i: int) -> int:
            if i > hi:
                return 0
            if i in memo:
                return memo[i]
            rob_this = nums[i] + solve(i + 2)
            skip_this = solve(i + 1)
            memo[i] = max(rob_this, skip_this)
            return memo[i]

        return solve(lo)

    return max(rob_range(0, n - 2), rob_range(1, n - 1))

