public int rob(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return nums[0];
    }
    return Math.max(robLinear(nums, 0, n - 2), robLinear(nums, 1, n - 1));
}

private int robLinear(int[] nums, int lo, int hi) {
    int rob1 = 0, rob2 = 0;
    for (int i = lo; i <= hi; i++) {
        int newRob = Math.max(rob2, rob1 + nums[i]);
        rob1 = rob2;
        rob2 = newRob;
    }
    return rob2;
}

