def rob(self, nums: list[int]) -> int:
    n = len(nums)
    if n == 1:
        return nums[0]

    def rob_linear(lo: int, hi: int) -> int:
        rob1, rob2 = 0, 0
        for i in range(lo, hi + 1):
            rob1, rob2 = rob2, max(rob2, rob1 + nums[i])
        return rob2

    return max(rob_linear(0, n - 2), rob_linear(1, n - 1))

